    P.append(dict(title=tr('Câu hỏi EASA', 'EASA questions'), bullets=[tr('Nhị phân, cổng, bộ cộng', 'Binary, gates, adders'), tr('Flip-flop, TTL/CMOS', 'Flip-flops, TTL/CMOS'), tr('Op-amp', 'Op-amps')], slides=[s9, s10, s11]))
